<?php
declare( strict_types = 1 );

namespace Automattic\WooCommerce\Internal\Blocks;

use Automattic\WooCommerce\Blocks\Domain\Package;

/**
 * Registers blocks generated by the block-library wp-build package.
 *
 * @since 11.0.0
 */
class BlockLibraryBlockTypeRegistry {

	/**
	 * Path for generated block metadata.
	 */
	private const BLOCK_METADATA_BUILD_PATH = 'assets/client/blocks/';

	/**
	 * Map of legacy block type class names to block metadata directory names.
	 */
	private const BLOCK_TYPES = array(
		'CategoryTitle' => 'category-title',
	);

	/**
	 * Package instance.
	 *
	 * @var Package
	 */
	private Package $package;

	/**
	 * Constructor.
	 *
	 * @param Package $package Package instance.
	 */
	public function __construct( Package $package ) {
		$this->package = $package;
	}

	/**
	 * Initialize hooks.
	 *
	 * @internal
	 */
	final public function init(): void {
		add_filter( 'woocommerce_get_block_types', array( $this, 'remove_migrated_block_types' ) );
		add_action( 'enqueue_block_editor_assets', array( $this, 'enqueue_block_editor_assets' ) );

		if ( did_action( 'init' ) ) {
			$this->register_block_types();
			return;
		}

		add_action( 'init', array( $this, 'register_block_types' ), 9 );
	}

	/**
	 * Enqueue editor assets for migrated block-library blocks.
	 */
	public function enqueue_block_editor_assets(): void {
		foreach ( self::BLOCK_TYPES as $block_name ) {
			$metadata_path = $this->get_block_metadata_path( $block_name );

			if ( ! $metadata_path ) {
				continue;
			}

			$metadata = wp_json_file_decode( $metadata_path . '/block.json', array( 'associative' => true ) );
			if ( ! is_array( $metadata ) || empty( $metadata['editorScript'] ) ) {
				continue;
			}

			$editor_scripts = is_array( $metadata['editorScript'] )
				? $metadata['editorScript']
				: array( $metadata['editorScript'] );

			foreach ( $editor_scripts as $editor_script ) {
				if ( is_string( $editor_script ) && '' !== $editor_script && 0 !== strpos( $editor_script, 'file:' ) ) {
					wp_enqueue_script( $editor_script );
				}
			}
		}
	}

	/**
	 * Remove migrated blocks from the legacy block type controller list.
	 *
	 * @param array<int, string> $block_types Legacy block type class names.
	 * @return array<int, string>
	 */
	public function remove_migrated_block_types( array $block_types ): array {
		return array_values( array_diff( $block_types, array_keys( self::BLOCK_TYPES ) ) );
	}

	/**
	 * Register all migrated block-library block types.
	 */
	public function register_block_types(): void {
		foreach ( self::BLOCK_TYPES as $block_name ) {
			$this->register_block_type_from_metadata( $block_name );
		}
	}

	/**
	 * Register a block type from the block-library metadata package.
	 *
	 * @param string $block_name Block metadata directory name.
	 * @return void
	 */
	public function register_block_type_from_metadata( string $block_name ): void {
		$metadata_path = $this->get_block_metadata_path( $block_name );

		if ( ! $metadata_path ) {
			return;
		}

		register_block_type_from_metadata( $metadata_path );
	}

	/**
	 * Get the metadata path for a block-library block.
	 *
	 * @param string $block_name Block directory name.
	 * @return string|false Path to metadata directory, or false if not found.
	 */
	public function get_block_metadata_path( string $block_name ) {
		$metadata_path = $this->package->get_path(
			self::BLOCK_METADATA_BUILD_PATH . $block_name . '/block.json'
		);

		if ( file_exists( $metadata_path ) ) {
			return dirname( $metadata_path );
		}

		return false;
	}
}
